  "sourcesContent": ["/**\n * Ajustes globales del juego.\n * Cambia n\u00FAmeros y textos de configuraci\u00F3n AQU\u00CD, no dentro de la l\u00F3gica.\n */\n\nexport const GAME = Object.freeze({\n  playerName: 'D. Diaz',\n  totalRounds: 4,\n  totalDays: 300,\n});\n\nexport const PAGES = Object.freeze({\n  start: 'index.html',\n  game: 'game.html',\n});\n\n/** Recursos de la nave (porcentajes de 0 a 100). */\nexport const RESOURCES = Object.freeze({\n  max: 100,\n  lowThreshold: 25,\n  start: Object.freeze({ energy: 70, lifeSupport: 70, shielding: 70 }),\n  labels: Object.freeze({\n    energy: 'Energy',\n    lifeSupport: 'Life Support',\n    shielding: 'Shielding',\n  }),\n});\n\nexport const STORAGE_KEYS = Object.freeze({\n  sound: 'survive-in-space:sound',\n  sepCache: 'survive-in-space:sep-cache',\n});\n\nexport const TIMING = Object.freeze({\n  liftOffMs: 1400,\n  fadeOutMs: 850,\n  typeMsPerChar: 22,\n  liveDataWaitMs: 3500,\n  minigameEndMs: 1500,\n});\n\n/**\n * API DONKI de la NASA (Space Weather Database Of Notifications, Knowledge, Information).\n * Devuelve eventos SEP (tormentas de part\u00EDculas solares) como una lista JSON.\n *  - Sin fechas, solo mira los \u00FAltimos 30 d\u00EDas (por eso a veces llega vac\u00EDa: []).\n *  - Con startDate / endDate (yyyy-MM-dd) puedes pedir un rango m\u00E1s amplio.\n */\nexport const DONKI = Object.freeze({\n  timeoutMs: 5000,\n  /** Ventanas de b\u00FAsqueda, de la m\u00E1s corta a la m\u00E1s larga (en d\u00EDas). */\n  lookbackDays: Object.freeze([30, 365, 1825]),\n  cacheTtlMs: 6 * 60 * 60 * 1000,\n  sources: Object.freeze([\n    Object.freeze({\n      id: 'ccmc',\n      baseUrl: 'https://ccmc.gsfc.nasa.gov/DONKI-API/get/SEP',\n      params: Object.freeze({ catalog: 'M2M_CATALOG', version: 'Latest' }),\n      dateParams: Object.freeze({ start: 'startDate', end: 'endDate' }),\n    }),\n    Object.freeze({\n      id: 'api-nasa-gov',\n      baseUrl: 'https://api.nasa.gov/DONKI/SEP',\n      // DEMO_KEY sirve para pruebas (l\u00EDmite bajo). Para publicar el juego, pide tu propia clave gratis en api.nasa.gov\n      params: Object.freeze({ api_key: 'DEMO_KEY' }),\n      dateParams: Object.freeze({ start: 'startDate', end: 'endDate' }),\n    }),\n  ]),\n});\n", "/** Acceso seguro a localStorage (puede fallar en modo privado o sin permisos). */\n\n/** @param {string} key @returns {string|null} */\nexport function readString(key) {\n  try {\n    return localStorage.getItem(key);\n  } catch {\n    return null;\n  }\n}\n\n/** @param {string} key @param {string} value */\nexport function writeString(key, value) {\n  try {\n    localStorage.setItem(key, value);\n    return true;\n  } catch {\n    return false;\n  }\n}\n\n/** @param {string} key @param {unknown} fallback */\nexport function readJson(key, fallback = null) {\n  const raw = readString(key);\n  if (raw === null) return fallback;\n  try {\n    return JSON.parse(raw);\n  } catch {\n    return fallback;\n  }\n}\n\n/** @param {string} key @param {unknown} value */\nexport function writeJson(key, value) {\n  return writeString(key, JSON.stringify(value));\n}\n", "/**\n * Efectos de sonido generados con Web Audio (no hay archivos de audio).\n * Todos suenan bajito. El estado \"silenciado\" se guarda en localStorage.\n */\nimport { STORAGE_KEYS } from '../config.js';\nimport { readString, writeString } from '../services/storage.js';\n\nlet context = null;\nlet muted = readString(STORAGE_KEYS.sound) === 'off';\n\nfunction getContext() {\n  if (!context) {\n    const AudioCtx = window.AudioContext ?? window.webkitAudioContext;\n    if (!AudioCtx) return null;\n    context = new AudioCtx();\n  }\n  if (context.state === 'suspended') context.resume();\n  return context;\n}\n\n// Los navegadores bloquean el audio hasta el primer gesto del jugador.\nfor (const type of ['pointerdown', 'keydown']) {\n  window.addEventListener(type, () => { if (context?.state === 'suspended') context.resume(); }, { passive: true });\n}\n\n/** Un tono corto con envolvente suave. */\nfunction tone({ freq, freqEnd, dur, type = 'square', vol = 0.03, delay = 0 }) {\n  if (muted) return;\n  const ctx = getContext();\n  if (!ctx) return;\n  const t = ctx.currentTime + delay;\n  const osc = ctx.createOscillator();\n  const gain = ctx.createGain();\n  osc.type = type;\n  osc.frequency.setValueAtTime(freq, t);\n  if (freqEnd) osc.frequency.exponentialRampToValueAtTime(freqEnd, t + dur);\n  gain.gain.setValueAtTime(0.0001, t);\n  gain.gain.linearRampToValueAtTime(vol, t + 0.01);\n  gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);\n  osc.connect(gain).connect(ctx.destination);\n  osc.start(t);\n  osc.stop(t + dur + 0.02);\n}\n\n/** Ruido filtrado (est\u00E1tica, motores). */\nfunction noise({ dur, from, to, vol }) {\n  if (muted) return;\n  const ctx = getContext();\n  if (!ctx) return;\n  const t = ctx.currentTime;\n  const buffer = ctx.createBuffer(1, Math.floor(ctx.sampleRate * dur), ctx.sampleRate);\n  const data = buffer.getChannelData(0);\n  for (let i = 0; i < data.length; i += 1) data[i] = Math.random() * 2 - 1;\n  const source = ctx.createBufferSource();\n  source.buffer = buffer;\n  const filter = ctx.createBiquadFilter();\n  filter.type = 'lowpass';\n  filter.frequency.setValueAtTime(from, t);\n  filter.frequency.exponentialRampToValueAtTime(to, t + dur);\n  const gain = ctx.createGain();\n  gain.gain.setValueAtTime(0.0001, t);\n  gain.gain.linearRampToValueAtTime(vol, t + dur * 0.3);\n  gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);\n  source.connect(filter).connect(gain).connect(ctx.destination);\n  source.start(t);\n}\n\nexport const sound = {\n  init() { getContext(); },\n  isMuted: () => muted,\n  toggle() {\n    muted = !muted;\n    writeString(STORAGE_KEYS.sound, muted ? 'off' : 'on');\n    if (!muted) { getContext(); this.page(); }\n    return muted;\n  },\n  // interfaz\n  tick() { tone({ freq: 520 + Math.random() * 90, dur: 0.035, type: 'triangle', vol: 0.018 }); },\n  page() {\n    tone({ freq: 660, dur: 0.07, type: 'triangle', vol: 0.035 });\n    tone({ freq: 880, dur: 0.09, type: 'triangle', vol: 0.035, delay: 0.07 });\n  },\n  choose() { tone({ freq: 420, freqEnd: 300, dur: 0.08, type: 'triangle', vol: 0.04 }); },\n  // escenas\n  liftOff() { noise({ dur: 1.4, from: 250, to: 1800, vol: 0.06 }); tone({ freq: 80, freqEnd: 200, dur: 1.2, type: 'sine', vol: 0.05 }); },\n  alarm() {\n    for (let i = 0; i < 3; i += 1) {\n      tone({ freq: 660, dur: 0.2, vol: 0.025, delay: i * 0.9 });\n      tone({ freq: 495, dur: 0.2, vol: 0.025, delay: i * 0.9 + 0.3 });\n    }\n  },\n  calm() {\n    tone({ freq: 392, dur: 0.25, type: 'sine', vol: 0.04 });\n    tone({ freq: 523, dur: 0.35, type: 'sine', vol: 0.04, delay: 0.2 });\n  },\n  // minijuegos\n  thrust() { noise({ dur: 0.16, from: 900, to: 300, vol: 0.05 }); },\n  glitch() { noise({ dur: 0.12, from: 3000, to: 1500, vol: 0.05 }); },\n  warning() { tone({ freq: 740, dur: 0.12, vol: 0.03 }); tone({ freq: 740, dur: 0.12, vol: 0.03, delay: 0.2 }); },\n  good() {\n    tone({ freq: 523, dur: 0.12, type: 'sine', vol: 0.05 });\n    tone({ freq: 784, dur: 0.18, type: 'sine', vol: 0.05, delay: 0.11 });\n  },\n  bad() { tone({ freq: 200, freqEnd: 130, dur: 0.3, type: 'sawtooth', vol: 0.035 }); },\n  win() { [523, 659, 784, 1046].forEach((freq, i) => tone({ freq, dur: 0.22, type: 'triangle', vol: 0.05, delay: i * 0.13 })); },\n  lose() { [392, 330, 262].forEach((freq, i) => tone({ freq, dur: 0.3, type: 'sawtooth', vol: 0.03, delay: i * 0.22 })); },\n};\n", "/**\n * Textos de la introducci\u00F3n (portada). Cada p\u00E1gina es un mensaje de la carta.\n * @typedef {import('../ui/letter.js').LetterPage} LetterPage\n */\n\n/** @param {string} playerName @returns {LetterPage[]} */\nexport function buildIntroPages(playerName) {\n  return [\n    { text: `Hello, ${playerName}. Welcome aboard Ares, a spaceship on its way to Mars.` },\n    { text: 'Your science mission: find out whether life could exist on the red planet by collecting data about its environment.' },\n    {\n      text: 'To get there, you will have to share your energy wisely, take care of your life support and protect the ship from radiation.',\n      notes: [\n        { term: 'Life support', text: 'the machines that give the crew air to breathe and clean water.' },\n        { term: 'Radiation', text: 'invisible energy that can hurt people and damage electronics.' },\n      ],\n    },\n    { text: 'The challenge: every decision counts. Survive 300 days in space to complete the mission.' },\n  ];\n}\n", "/** Luces rojas y se\u00F1ales de alerta (los estilos viven en css/alert.css). */\nexport function setAlert(on) {\n  document.body.classList.toggle('is-alert', on);\n}\n\nexport function isAlertOn() {\n  return document.body.classList.contains('is-alert');\n}\n", "/**\n * Utilidades para construir elementos del DOM de forma SEGURA.\n * Usamos createElement/textContent en lugar de innerHTML, as\u00ED los textos que vienen\n * de fuera (por ejemplo, de la API de la NASA) nunca se interpretan como HTML.\n */\n\n/**\n * @param {string} tag\n * @param {Record<string, unknown>} [attrs] class, dataset, on (eventos), o cualquier atributo\n * @param {...(Node|string|number|false|null|undefined|Array)} children\n * @returns {HTMLElement}\n */\nexport function el(tag, attrs = {}, ...children) {\n  const node = document.createElement(tag);\n  for (const [key, value] of Object.entries(attrs ?? {})) {\n    if (value === undefined || value === null || value === false) continue;\n    if (key === 'class') node.className = String(value);\n    else if (key === 'dataset') Object.assign(node.dataset, value);\n    else if (key === 'on') for (const [event, handler] of Object.entries(value)) node.addEventListener(event, handler);\n    else if (value === true) node.setAttribute(key, '');\n    else node.setAttribute(key, String(value));\n  }\n  node.append(...flatten(children));\n  return node;\n}\n\n/** Igual que el(), pero para elementos SVG. */\nexport function svg(tag, attrs = {}, ...children) {\n  const node = document.createElementNS('http://www.w3.org/2000/svg', tag);\n  for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, String(value));\n  node.append(...flatten(children));\n  return node;\n}\n\nfunction flatten(children) {\n  return children\n    .flat(Infinity)\n    .filter((child) => child !== null && child !== undefined && child !== false)\n    .map((child) => (child instanceof Node ? child : document.createTextNode(String(child))));\n}\n\n/** Reemplaza todo el contenido de un contenedor. */\nexport function mount(container, ...nodes) {\n  container.replaceChildren(...nodes);\n}\n\nexport const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\n\nexport const prefersReducedMotion = () =>\n  window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;\n\n/** Mueve el foco a un t\u00EDtulo para que los lectores de pantalla anuncien la nueva pantalla. */\nexport function focusTitle(root) {\n  const title = root.querySelector('[tabindex=\"-1\"]');\n  title?.focus({ preventScroll: true });\n}\n", "/**\n * Carta: cuadro de texto estilo pergamino con efecto de escritura, notas de ciencia,\n * flecha para continuar y puntos de p\u00E1gina.\n *\n * @typedef {{ term?: string, text: string }} Note\n * @typedef {{ text: string, notes?: Note[], notesTitle?: string, extra?: () => Node }} LetterPage\n *   - extra: funci\u00F3n que devuelve contenido adicional (por ejemplo, chips) que aparece al terminar de escribir.\n */\nimport { TIMING } from '../config.js';\nimport { sound } from '../audio/sound.js';\nimport { el, mount, prefersReducedMotion, svg } from './dom.js';\n\nlet activeLetter = null;\n\nfunction arrowIcon() {\n  const rects = [[5, 0, 1, 9], [6, 1, 1, 7], [7, 2, 1, 5], [8, 3, 1, 3], [9, 4, 1, 1], [0, 3, 5, 3]];\n  return svg(\n    'svg',\n    { viewBox: '0 0 10 9', fill: 'currentColor', 'shape-rendering': 'crispEdges', 'aria-hidden': 'true' },\n    ...rects.map(([x, y, width, height]) => svg('rect', { x, y, width, height })),\n  );\n}\n\n/** Cierra la carta que est\u00E9 abierta (quita sus temporizadores y atajos de teclado). */\nexport function closeLetter() {\n  activeLetter?.dispose();\n  activeLetter = null;\n}\n\n/**\n * Muestra una secuencia de p\u00E1ginas. La promesa se cumple cuando el jugador pulsa la flecha\n * en la \u00FAltima p\u00E1gina.\n *\n * @param {object} options\n * @param {HTMLElement} options.container donde se dibuja la carta\n * @param {LetterPage[]} options.pages\n * @param {string} [options.speaker] qui\u00E9n habla (p. ej. \"Ship System\")\n * @param {string} [options.finalLabel] texto junto a la flecha en la \u00FAltima p\u00E1gina\n * @param {boolean} [options.skippable] muestra la \u2715 para saltar a la \u00FAltima p\u00E1gina\n * @param {(index: number, total: number) => void} [options.onShow]\n * @returns {Promise<void>}\n */\nexport function openLetter({ container, pages, speaker, finalLabel = '', skippable = false, onShow }) {\n  closeLetter();\n  return new Promise((resolve) => {\n    const last = pages.length - 1;\n    const instant = prefersReducedMotion();\n    let index = 0;\n    let typing = false;\n    let typedLength = 0;\n    let timer = null;\n\n    const live = el('p', { class: 'sr', 'aria-live': 'polite' });\n    const extraLive = el('p', { class: 'sr', 'aria-live': 'polite' });\n    const textEl = el('p', { class: 'letter-text', 'aria-hidden': 'true' });\n    const notesEl = el('div', { class: 'letter-notes', 'aria-hidden': 'true' });\n    const extraEl = el('div', { class: 'letter-extra' });\n    const labelEl = el('span', { class: 'label' });\n    const nextButton = el('button', { type: 'button', class: 'letter-next' }, labelEl, arrowIcon());\n    const dots = pages.map(() => el('span', { class: 'dot' }));\n    const skipButton = skippable\n      ? el('button', { type: 'button', class: 'letter-skip', 'aria-label': 'Skip to the last page' }, '\\u00D7')\n      : null;\n\n    const root = el(\n      'div',\n      { class: 'letter', role: 'dialog', 'aria-label': speaker ?? 'Message' },\n      speaker ? el('span', { class: 'letter-speaker' }, speaker) : null,\n      skipButton,\n      live, textEl, notesEl, extraEl, extraLive,\n      el('div', { class: 'letter-pager', 'aria-hidden': 'true' }, dots),\n      nextButton,\n    );\n    mount(container, root);\n\n    const paintText = (count) => {\n      const full = pages[index].text;\n      textEl.replaceChildren(el('span', {}, full.slice(0, count)), el('span', { class: 'hidden-text' }, full.slice(count)));\n    };\n\n    const finishTyping = () => {\n      clearTimeout(timer);\n      typing = false;\n      paintText(pages[index].text.length);\n      notesEl.removeAttribute('data-hidden');\n      extraEl.removeAttribute('data-hidden');\n      const extraText = extraEl.textContent?.trim();\n      if (extraText) extraLive.textContent = extraText;\n    };\n\n    const typeNext = () => {\n      const text = pages[index].text;\n      if (typedLength >= text.length) { finishTyping(); return; }\n      typedLength += 1;\n      paintText(typedLength);\n      const char = text[typedLength - 1];\n      if (char !== ' ' && typedLength % 3 === 0) sound.tick();\n      const pause = '.!?'.includes(char) ? 220 : char === ',' ? 100 : 0;\n      timer = setTimeout(typeNext, TIMING.typeMsPerChar + pause);\n    };\n\n    const showPage = () => {\n      const page = pages[index];\n      const notes = page.notes ?? [];\n      dots.forEach((dot, i) => dot.classList.toggle('active', i === index));\n      notesEl.replaceChildren(\n        ...(notes.length\n          ? [el('p', { class: 'notes-title' }, page.notesTitle ?? 'Quick science'),\n             ...notes.map((n) => el('p', {}, n.term ? el('b', {}, `${n.term}: `) : null, n.text))]\n          : []),\n      );\n      notesEl.style.display = notes.length ? '' : 'none';\n      notesEl.setAttribute('data-hidden', '');\n      extraEl.replaceChildren(...(page.extra ? [page.extra()] : []));\n      extraEl.setAttribute('data-hidden', '');\n      extraLive.textContent = '';\n      live.textContent = `Page ${index + 1} of ${pages.length}. ${page.text}${notes.map((n) => ` ${page.notesTitle ?? 'Quick science'}. ${n.term ? `${n.term}: ` : ''}${n.text}`).join('')}`;\n      labelEl.textContent = index === last ? finalLabel : '';\n      nextButton.setAttribute('aria-label', index === last ? (finalLabel || 'Continue') : 'Next page');\n      if (skipButton) skipButton.style.display = index === last ? 'none' : '';\n      typedLength = 0;\n      onShow?.(index, pages.length);\n      if (instant) { finishTyping(); return; }\n      typing = true;\n      paintText(0);\n      timer = setTimeout(typeNext, 250);\n    };\n\n    const advance = () => {\n      if (typing) { finishTyping(); return; }\n      sound.page();\n      if (index < last) { index += 1; showPage(); return; }\n      closeLetter();\n      resolve();\n    };\n\n    const skipToEnd = () => {\n      sound.page();\n      clearTimeout(timer);\n      typing = false;\n      index = last;\n      showPage();\n      finishTyping();\n    };\n\n    const onKey = (event) => {\n      if (event.ctrlKey || event.metaKey || event.altKey) return;\n      if (/^(BUTTON|A|INPUT)$/.test(event.target?.tagName ?? '')) return; // un bot\u00F3n enfocado ya reacciona a Enter/Espacio\n      if (['Enter', ' ', 'ArrowRight'].includes(event.key)) { event.preventDefault(); advance(); }\n    };\n\n    nextButton.addEventListener('click', advance);\n    skipButton?.addEventListener('click', skipToEnd);\n    document.addEventListener('keydown', onKey);\n    activeLetter = { dispose() { clearTimeout(timer); document.removeEventListener('keydown', onKey); } };\n\n    showPage();\n    nextButton.focus({ preventScroll: true });\n  });\n}\n", "import { sound } from '../audio/sound.js';\n\n/** Conecta el bot\u00F3n \"Sound: on/off\". @param {HTMLElement} button */\nexport function initSoundToggle(button) {\n  const paint = () => {\n    button.textContent = `Sound: ${sound.isMuted() ? 'off' : 'on'}`;\n    button.setAttribute('aria-pressed', String(!sound.isMuted()));\n  };\n  button.addEventListener('click', () => { sound.toggle(); paint(); });\n  paint();\n}\n", "/**\n * Punto de entrada de index.html (portada):\n * Play \u2192 desaparecen los textos \u2192 la nave sube \u2192 intro en carta \u2192 alerta roja \u2192 entra a la cabina.\n */\nimport { GAME, PAGES, TIMING } from '../config.js';\nimport { sound } from '../audio/sound.js';\nimport { buildIntroPages } from '../data/intro.js';\nimport { setAlert, isAlertOn } from '../ui/alert.js';\nimport { openLetter } from '../ui/letter.js';\nimport { initSoundToggle } from '../ui/sound-toggle.js';\n\nconst playButton = document.getElementById('play-button');\nconst intro = document.getElementById('intro');\nlet started = false;\n\ninitSoundToggle(document.getElementById('sound-toggle'));\n\nasync function showIntro() {\n  document.body.classList.add('is-cruising');\n  intro.hidden = false;\n  await openLetter({\n    container: intro,\n    pages: buildIntroPages(GAME.playerName),\n    skippable: true,\n    finalLabel: 'Respond',\n    onShow(index, total) {\n      // En el \u00FAltimo mensaje (el reto) se enciende la alerta.\n      if (index === total - 1 && !isAlertOn()) {\n        setAlert(true);\n        sound.alarm();\n      }\n    },\n  });\n  document.body.classList.add('is-leaving'); // fundido a negro\n  setTimeout(() => { window.location.href = PAGES.game; }, TIMING.fadeOutMs);\n}\n\nfunction start() {\n  if (started) return;\n  started = true;\n  sound.init();\n  sound.liftOff();\n  document.body.classList.add('is-lifting-off'); // textos fuera y la nave sube\n  setTimeout(showIntro, TIMING.liftOffMs);\n}\n\nplayButton.addEventListener('click', start);\ndocument.addEventListener('keydown', (event) => {\n  if ((event.key === 'Enter' || event.key === ' ') && !started && document.activeElement?.id !== 'sound-toggle') {\n    event.preventDefault();\n    start();\n  }\n});\n\n// Si vuelve con el bot\u00F3n \"atr\u00E1s\", dejamos la portada como nueva.\nwindow.addEventListener('pageshow', (event) => { if (event.persisted) window.location.reload(); });\n"],
=======
  "sourcesContent": ["/**\r\n * Ajustes globales del juego.\r\n * Cambia n\u00FAmeros y textos de configuraci\u00F3n AQU\u00CD, no dentro de la l\u00F3gica.\r\n */\r\n\r\nexport const GAME = Object.freeze({\r\n  playerName: 'D. Diaz',\r\n  totalRounds: 10,\r\n  totalDays: 300,\r\n});\r\n\r\nexport const PAGES = Object.freeze({\r\n  start: 'index.html',\r\n  game: 'game.html',\r\n});\r\n\r\n/** Recursos de la nave (porcentajes de 0 a 100). */\r\nexport const RESOURCES = Object.freeze({\r\n  max: 100,\r\n  lowThreshold: 25,\r\n  start: Object.freeze({ energy: 70, lifeSupport: 70, shielding: 70 }),\r\n  labels: Object.freeze({\r\n    energy: 'Energy',\r\n    lifeSupport: 'Life Support',\r\n    shielding: 'Shielding',\r\n  }),\r\n});\r\n\r\nexport const STORAGE_KEYS = Object.freeze({\r\n  sound: 'survive-in-space:sound',\r\n  sepCache: 'survive-in-space:sep-cache',\r\n});\r\n\r\nexport const TIMING = Object.freeze({\r\n  liftOffMs: 1400,\r\n  fadeOutMs: 850,\r\n  typeMsPerChar: 22,\r\n  liveDataWaitMs: 3500,\r\n  minigameEndMs: 1500,\r\n});\r\n\r\n/**\r\n * API DONKI de la NASA (Space Weather Database Of Notifications, Knowledge, Information).\r\n * Devuelve eventos SEP (tormentas de part\u00EDculas solares) como una lista JSON.\r\n *  - Sin fechas, solo mira los \u00FAltimos 30 d\u00EDas (por eso a veces llega vac\u00EDa: []).\r\n *  - Con startDate / endDate (yyyy-MM-dd) puedes pedir un rango m\u00E1s amplio.\r\n */\r\nexport const DONKI = Object.freeze({\r\n  timeoutMs: 5000,\r\n  /** Ventanas de b\u00FAsqueda, de la m\u00E1s corta a la m\u00E1s larga (en d\u00EDas). */\r\n  lookbackDays: Object.freeze([30, 365, 1825]),\r\n  cacheTtlMs: 6 * 60 * 60 * 1000,\r\n  sources: Object.freeze([\r\n    Object.freeze({\r\n      id: 'ccmc',\r\n      baseUrl: 'https://ccmc.gsfc.nasa.gov/DONKI-API/get/SEP',\r\n      params: Object.freeze({ catalog: 'M2M_CATALOG', version: 'Latest' }),\r\n      dateParams: Object.freeze({ start: 'startDate', end: 'endDate' }),\r\n    }),\r\n    Object.freeze({\r\n      id: 'api-nasa-gov',\r\n      baseUrl: 'https://api.nasa.gov/DONKI/SEP',\r\n      // DEMO_KEY sirve para pruebas (l\u00EDmite bajo). Para publicar el juego, pide tu propia clave gratis en api.nasa.gov\r\n      params: Object.freeze({ api_key: 'DEMO_KEY' }),\r\n      dateParams: Object.freeze({ start: 'startDate', end: 'endDate' }),\r\n    }),\r\n  ]),\r\n});\r\n", "/** Acceso seguro a localStorage (puede fallar en modo privado o sin permisos). */\r\n\r\n/** @param {string} key @returns {string|null} */\r\nexport function readString(key) {\r\n  try {\r\n    return localStorage.getItem(key);\r\n  } catch {\r\n    return null;\r\n  }\r\n}\r\n\r\n/** @param {string} key @param {string} value */\r\nexport function writeString(key, value) {\r\n  try {\r\n    localStorage.setItem(key, value);\r\n    return true;\r\n  } catch {\r\n    return false;\r\n  }\r\n}\r\n\r\n/** @param {string} key @param {unknown} fallback */\r\nexport function readJson(key, fallback = null) {\r\n  const raw = readString(key);\r\n  if (raw === null) return fallback;\r\n  try {\r\n    return JSON.parse(raw);\r\n  } catch {\r\n    return fallback;\r\n  }\r\n}\r\n\r\n/** @param {string} key @param {unknown} value */\r\nexport function writeJson(key, value) {\r\n  return writeString(key, JSON.stringify(value));\r\n}\r\n", "/**\r\n * Efectos de sonido generados con Web Audio (no hay archivos de audio).\r\n * Todos suenan bajito. El estado \"silenciado\" se guarda en localStorage.\r\n */\r\nimport { STORAGE_KEYS } from '../config.js';\r\nimport { readString, writeString } from '../services/storage.js';\r\n\r\nlet context = null;\r\nlet muted = readString(STORAGE_KEYS.sound) === 'off';\r\n\r\nfunction getContext() {\r\n  if (!context) {\r\n    const AudioCtx = window.AudioContext ?? window.webkitAudioContext;\r\n    if (!AudioCtx) return null;\r\n    context = new AudioCtx();\r\n  }\r\n  if (context.state === 'suspended') context.resume();\r\n  return context;\r\n}\r\n\r\n// Los navegadores bloquean el audio hasta el primer gesto del jugador.\r\nfor (const type of ['pointerdown', 'keydown']) {\r\n  window.addEventListener(type, () => { if (context?.state === 'suspended') context.resume(); }, { passive: true });\r\n}\r\n\r\n/** Un tono corto con envolvente suave. */\r\nfunction tone({ freq, freqEnd, dur, type = 'square', vol = 0.03, delay = 0 }) {\r\n  if (muted) return;\r\n  const ctx = getContext();\r\n  if (!ctx) return;\r\n  const t = ctx.currentTime + delay;\r\n  const osc = ctx.createOscillator();\r\n  const gain = ctx.createGain();\r\n  osc.type = type;\r\n  osc.frequency.setValueAtTime(freq, t);\r\n  if (freqEnd) osc.frequency.exponentialRampToValueAtTime(freqEnd, t + dur);\r\n  gain.gain.setValueAtTime(0.0001, t);\r\n  gain.gain.linearRampToValueAtTime(vol, t + 0.01);\r\n  gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);\r\n  osc.connect(gain).connect(ctx.destination);\r\n  osc.start(t);\r\n  osc.stop(t + dur + 0.02);\r\n}\r\n\r\n/** Ruido filtrado (est\u00E1tica, motores). */\r\nfunction noise({ dur, from, to, vol }) {\r\n  if (muted) return;\r\n  const ctx = getContext();\r\n  if (!ctx) return;\r\n  const t = ctx.currentTime;\r\n  const buffer = ctx.createBuffer(1, Math.floor(ctx.sampleRate * dur), ctx.sampleRate);\r\n  const data = buffer.getChannelData(0);\r\n  for (let i = 0; i < data.length; i += 1) data[i] = Math.random() * 2 - 1;\r\n  const source = ctx.createBufferSource();\r\n  source.buffer = buffer;\r\n  const filter = ctx.createBiquadFilter();\r\n  filter.type = 'lowpass';\r\n  filter.frequency.setValueAtTime(from, t);\r\n  filter.frequency.exponentialRampToValueAtTime(to, t + dur);\r\n  const gain = ctx.createGain();\r\n  gain.gain.setValueAtTime(0.0001, t);\r\n  gain.gain.linearRampToValueAtTime(vol, t + dur * 0.3);\r\n  gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);\r\n  source.connect(filter).connect(gain).connect(ctx.destination);\r\n  source.start(t);\r\n}\r\n\r\nexport const sound = {\r\n  init() { getContext(); },\r\n  isMuted: () => muted,\r\n  toggle() {\r\n    muted = !muted;\r\n    writeString(STORAGE_KEYS.sound, muted ? 'off' : 'on');\r\n    if (!muted) { getContext(); this.page(); }\r\n    return muted;\r\n  },\r\n  // interfaz\r\n  tick() { tone({ freq: 520 + Math.random() * 90, dur: 0.035, type: 'triangle', vol: 0.018 }); },\r\n  page() {\r\n    tone({ freq: 660, dur: 0.07, type: 'triangle', vol: 0.035 });\r\n    tone({ freq: 880, dur: 0.09, type: 'triangle', vol: 0.035, delay: 0.07 });\r\n  },\r\n  choose() { tone({ freq: 420, freqEnd: 300, dur: 0.08, type: 'triangle', vol: 0.04 }); },\r\n  // escenas\r\n  liftOff() { noise({ dur: 1.4, from: 250, to: 1800, vol: 0.06 }); tone({ freq: 80, freqEnd: 200, dur: 1.2, type: 'sine', vol: 0.05 }); },\r\n  alarm() {\r\n    for (let i = 0; i < 3; i += 1) {\r\n      tone({ freq: 660, dur: 0.2, vol: 0.025, delay: i * 0.9 });\r\n      tone({ freq: 495, dur: 0.2, vol: 0.025, delay: i * 0.9 + 0.3 });\r\n    }\r\n  },\r\n  calm() {\r\n    tone({ freq: 392, dur: 0.25, type: 'sine', vol: 0.04 });\r\n    tone({ freq: 523, dur: 0.35, type: 'sine', vol: 0.04, delay: 0.2 });\r\n  },\r\n  // minijuegos\r\n  thrust() { noise({ dur: 0.16, from: 900, to: 300, vol: 0.05 }); },\r\n  glitch() { noise({ dur: 0.12, from: 3000, to: 1500, vol: 0.05 }); },\r\n  warning() { tone({ freq: 740, dur: 0.12, vol: 0.03 }); tone({ freq: 740, dur: 0.12, vol: 0.03, delay: 0.2 }); },\r\n  good() {\r\n    tone({ freq: 523, dur: 0.12, type: 'sine', vol: 0.05 });\r\n    tone({ freq: 784, dur: 0.18, type: 'sine', vol: 0.05, delay: 0.11 });\r\n  },\r\n  bad() { tone({ freq: 200, freqEnd: 130, dur: 0.3, type: 'sawtooth', vol: 0.035 }); },\r\n  win() { [523, 659, 784, 1046].forEach((freq, i) => tone({ freq, dur: 0.22, type: 'triangle', vol: 0.05, delay: i * 0.13 })); },\r\n  lose() { [392, 330, 262].forEach((freq, i) => tone({ freq, dur: 0.3, type: 'sawtooth', vol: 0.03, delay: i * 0.22 })); },\r\n};\r\n", "/**\r\n * Textos de la introducci\u00F3n (portada). Cada p\u00E1gina es un mensaje de la carta.\r\n * @typedef {import('../ui/letter.js').LetterPage} LetterPage\r\n */\r\n\r\n/** @param {string} playerName @returns {LetterPage[]} */\r\nexport function buildIntroPages(playerName) {\r\n  return [\r\n    { text: `Hello, ${playerName}. Welcome aboard Ares, a spaceship on its way to Mars.` },\r\n    { text: 'Your science mission: find out whether life could exist on the red planet by collecting data about its environment.' },\r\n    {\r\n      text: 'To get there, you will have to share your energy wisely, take care of your life support and protect the ship from radiation.',\r\n      notes: [\r\n        { term: 'Life support', text: 'the machines that give the crew air to breathe and clean water.' },\r\n        { term: 'Radiation', text: 'invisible energy that can hurt people and damage electronics.' },\r\n      ],\r\n    },\r\n    { text: 'The challenge: every decision counts. Survive 300 days in space to complete the mission.' },\r\n  ];\r\n}\r\n", "/** Luces rojas y se\u00F1ales de alerta (los estilos viven en css/alert.css). */\r\nexport function setAlert(on) {\r\n  document.body.classList.toggle('is-alert', on);\r\n}\r\n\r\nexport function isAlertOn() {\r\n  return document.body.classList.contains('is-alert');\r\n}\r\n", "/**\r\n * Utilidades para construir elementos del DOM de forma SEGURA.\r\n * Usamos createElement/textContent en lugar de innerHTML, as\u00ED los textos que vienen\r\n * de fuera (por ejemplo, de la API de la NASA) nunca se interpretan como HTML.\r\n */\r\n\r\n/**\r\n * @param {string} tag\r\n * @param {Record<string, unknown>} [attrs] class, dataset, on (eventos), o cualquier atributo\r\n * @param {...(Node|string|number|false|null|undefined|Array)} children\r\n * @returns {HTMLElement}\r\n */\r\nexport function el(tag, attrs = {}, ...children) {\r\n  const node = document.createElement(tag);\r\n  for (const [key, value] of Object.entries(attrs ?? {})) {\r\n    if (value === undefined || value === null || value === false) continue;\r\n    if (key === 'class') node.className = String(value);\r\n    else if (key === 'dataset') Object.assign(node.dataset, value);\r\n    else if (key === 'on') for (const [event, handler] of Object.entries(value)) node.addEventListener(event, handler);\r\n    else if (value === true) node.setAttribute(key, '');\r\n    else node.setAttribute(key, String(value));\r\n  }\r\n  node.append(...flatten(children));\r\n  return node;\r\n}\r\n\r\n/** Igual que el(), pero para elementos SVG. */\r\nexport function svg(tag, attrs = {}, ...children) {\r\n  const node = document.createElementNS('http://www.w3.org/2000/svg', tag);\r\n  for (const [key, value] of Object.entries(attrs)) node.setAttribute(key, String(value));\r\n  node.append(...flatten(children));\r\n  return node;\r\n}\r\n\r\nfunction flatten(children) {\r\n  return children\r\n    .flat(Infinity)\r\n    .filter((child) => child !== null && child !== undefined && child !== false)\r\n    .map((child) => (child instanceof Node ? child : document.createTextNode(String(child))));\r\n}\r\n\r\n/** Reemplaza todo el contenido de un contenedor. */\r\nexport function mount(container, ...nodes) {\r\n  container.replaceChildren(...nodes);\r\n}\r\n\r\nexport const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\r\n\r\nexport const prefersReducedMotion = () =>\r\n  window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;\r\n\r\n/** Mueve el foco a un t\u00EDtulo para que los lectores de pantalla anuncien la nueva pantalla. */\r\nexport function focusTitle(root) {\r\n  const title = root.querySelector('[tabindex=\"-1\"]');\r\n  title?.focus({ preventScroll: true });\r\n}\r\n", "/**\r\n * Carta: cuadro de texto estilo pergamino con efecto de escritura, notas de ciencia,\r\n * flecha para continuar y puntos de p\u00E1gina.\r\n *\r\n * @typedef {{ term?: string, text: string }} Note\r\n * @typedef {{ text: string, notes?: Note[], notesTitle?: string, extra?: () => Node }} LetterPage\r\n *   - extra: funci\u00F3n que devuelve contenido adicional (por ejemplo, chips) que aparece al terminar de escribir.\r\n */\r\nimport { TIMING } from '../config.js';\r\nimport { sound } from '../audio/sound.js';\r\nimport { el, mount, prefersReducedMotion, svg } from './dom.js';\r\n\r\nlet activeLetter = null;\r\n\r\nfunction arrowIcon() {\r\n  const rects = [[5, 0, 1, 9], [6, 1, 1, 7], [7, 2, 1, 5], [8, 3, 1, 3], [9, 4, 1, 1], [0, 3, 5, 3]];\r\n  return svg(\r\n    'svg',\r\n    { viewBox: '0 0 10 9', fill: 'currentColor', 'shape-rendering': 'crispEdges', 'aria-hidden': 'true' },\r\n    ...rects.map(([x, y, width, height]) => svg('rect', { x, y, width, height })),\r\n  );\r\n}\r\n\r\n/** Cierra la carta que est\u00E9 abierta (quita sus temporizadores y atajos de teclado). */\r\nexport function closeLetter() {\r\n  activeLetter?.dispose();\r\n  activeLetter = null;\r\n}\r\n\r\n/**\r\n * Muestra una secuencia de p\u00E1ginas. La promesa se cumple cuando el jugador pulsa la flecha\r\n * en la \u00FAltima p\u00E1gina.\r\n *\r\n * @param {object} options\r\n * @param {HTMLElement} options.container donde se dibuja la carta\r\n * @param {LetterPage[]} options.pages\r\n * @param {string} [options.speaker] qui\u00E9n habla (p. ej. \"Ship System\")\r\n * @param {string} [options.finalLabel] texto junto a la flecha en la \u00FAltima p\u00E1gina\r\n * @param {boolean} [options.skippable] muestra la \u2715 para saltar a la \u00FAltima p\u00E1gina\r\n * @param {(index: number, total: number) => void} [options.onShow]\r\n * @returns {Promise<void>}\r\n */\r\nexport function openLetter({ container, pages, speaker, finalLabel = '', skippable = false, onShow }) {\r\n  closeLetter();\r\n  return new Promise((resolve) => {\r\n    const last = pages.length - 1;\r\n    const instant = prefersReducedMotion();\r\n    let index = 0;\r\n    let typing = false;\r\n    let typedLength = 0;\r\n    let timer = null;\r\n\r\n    const live = el('p', { class: 'sr', 'aria-live': 'polite' });\r\n    const extraLive = el('p', { class: 'sr', 'aria-live': 'polite' });\r\n    const textEl = el('p', { class: 'letter-text', 'aria-hidden': 'true' });\r\n    const notesEl = el('div', { class: 'letter-notes', 'aria-hidden': 'true' });\r\n    const extraEl = el('div', { class: 'letter-extra' });\r\n    const labelEl = el('span', { class: 'label' });\r\n    const nextButton = el('button', { type: 'button', class: 'letter-next' }, labelEl, arrowIcon());\r\n    const dots = pages.map(() => el('span', { class: 'dot' }));\r\n    const skipButton = skippable\r\n      ? el('button', { type: 'button', class: 'letter-skip', 'aria-label': 'Skip to the last page' }, '\\u00D7')\r\n      : null;\r\n\r\n    const root = el(\r\n      'div',\r\n      { class: 'letter', role: 'dialog', 'aria-label': speaker ?? 'Message' },\r\n      speaker ? el('span', { class: 'letter-speaker' }, speaker) : null,\r\n      skipButton,\r\n      live, textEl, notesEl, extraEl, extraLive,\r\n      el('div', { class: 'letter-pager', 'aria-hidden': 'true' }, dots),\r\n      nextButton,\r\n    );\r\n    mount(container, root);\r\n\r\n    const paintText = (count) => {\r\n      const full = pages[index].text;\r\n      textEl.replaceChildren(el('span', {}, full.slice(0, count)), el('span', { class: 'hidden-text' }, full.slice(count)));\r\n    };\r\n\r\n    const finishTyping = () => {\r\n      clearTimeout(timer);\r\n      typing = false;\r\n      paintText(pages[index].text.length);\r\n      notesEl.removeAttribute('data-hidden');\r\n      extraEl.removeAttribute('data-hidden');\r\n      const extraText = extraEl.textContent?.trim();\r\n      if (extraText) extraLive.textContent = extraText;\r\n    };\r\n\r\n    const typeNext = () => {\r\n      const text = pages[index].text;\r\n      if (typedLength >= text.length) { finishTyping(); return; }\r\n      typedLength += 1;\r\n      paintText(typedLength);\r\n      const char = text[typedLength - 1];\r\n      if (char !== ' ' && typedLength % 3 === 0) sound.tick();\r\n      const pause = '.!?'.includes(char) ? 220 : char === ',' ? 100 : 0;\r\n      timer = setTimeout(typeNext, TIMING.typeMsPerChar + pause);\r\n    };\r\n\r\n    const showPage = () => {\r\n      const page = pages[index];\r\n      const notes = page.notes ?? [];\r\n      dots.forEach((dot, i) => dot.classList.toggle('active', i === index));\r\n      notesEl.replaceChildren(\r\n        ...(notes.length\r\n          ? [el('p', { class: 'notes-title' }, page.notesTitle ?? 'Quick science'),\r\n             ...notes.map((n) => el('p', {}, n.term ? el('b', {}, `${n.term}: `) : null, n.text))]\r\n          : []),\r\n      );\r\n      notesEl.style.display = notes.length ? '' : 'none';\r\n      notesEl.setAttribute('data-hidden', '');\r\n      extraEl.replaceChildren(...(page.extra ? [page.extra()] : []));\r\n      extraEl.setAttribute('data-hidden', '');\r\n      extraLive.textContent = '';\r\n      live.textContent = `Page ${index + 1} of ${pages.length}. ${page.text}${notes.map((n) => ` ${page.notesTitle ?? 'Quick science'}. ${n.term ? `${n.term}: ` : ''}${n.text}`).join('')}`;\r\n      labelEl.textContent = index === last ? finalLabel : '';\r\n      nextButton.setAttribute('aria-label', index === last ? (finalLabel || 'Continue') : 'Next page');\r\n      if (skipButton) skipButton.style.display = index === last ? 'none' : '';\r\n      typedLength = 0;\r\n      onShow?.(index, pages.length);\r\n      if (instant) { finishTyping(); return; }\r\n      typing = true;\r\n      paintText(0);\r\n      timer = setTimeout(typeNext, 250);\r\n    };\r\n\r\n    const advance = () => {\r\n      if (typing) { finishTyping(); return; }\r\n      sound.page();\r\n      if (index < last) { index += 1; showPage(); return; }\r\n      closeLetter();\r\n      resolve();\r\n    };\r\n\r\n    const skipToEnd = () => {\r\n      sound.page();\r\n      clearTimeout(timer);\r\n      typing = false;\r\n      index = last;\r\n      showPage();\r\n      finishTyping();\r\n    };\r\n\r\n    const onKey = (event) => {\r\n      if (event.ctrlKey || event.metaKey || event.altKey) return;\r\n      if (/^(BUTTON|A|INPUT)$/.test(event.target?.tagName ?? '')) return; // un bot\u00F3n enfocado ya reacciona a Enter/Espacio\r\n      if (['Enter', ' ', 'ArrowRight'].includes(event.key)) { event.preventDefault(); advance(); }\r\n    };\r\n\r\n    nextButton.addEventListener('click', advance);\r\n    skipButton?.addEventListener('click', skipToEnd);\r\n    document.addEventListener('keydown', onKey);\r\n    activeLetter = { dispose() { clearTimeout(timer); document.removeEventListener('keydown', onKey); } };\r\n\r\n    showPage();\r\n    nextButton.focus({ preventScroll: true });\r\n  });\r\n}\r\n", "import { sound } from '../audio/sound.js';\r\n\r\n/** Conecta el bot\u00F3n \"Sound: on/off\". @param {HTMLElement} button */\r\nexport function initSoundToggle(button) {\r\n  const paint = () => {\r\n    button.textContent = `Sound: ${sound.isMuted() ? 'off' : 'on'}`;\r\n    button.setAttribute('aria-pressed', String(!sound.isMuted()));\r\n  };\r\n  button.addEventListener('click', () => { sound.toggle(); paint(); });\r\n  paint();\r\n}\r\n", "/**\r\n * Punto de entrada de index.html (portada):\r\n * Play \u2192 desaparecen los textos \u2192 la nave sube \u2192 intro en carta \u2192 alerta roja \u2192 entra a la cabina.\r\n */\r\nimport { GAME, PAGES, TIMING } from '../config.js';\r\nimport { sound } from '../audio/sound.js';\r\nimport { buildIntroPages } from '../data/intro.js';\r\nimport { setAlert, isAlertOn } from '../ui/alert.js';\r\nimport { openLetter } from '../ui/letter.js';\r\nimport { initSoundToggle } from '../ui/sound-toggle.js';\r\n\r\nconst playButton = document.getElementById('play-button');\r\nconst intro = document.getElementById('intro');\r\nlet started = false;\r\n\r\ninitSoundToggle(document.getElementById('sound-toggle'));\r\n\r\nasync function showIntro() {\r\n  document.body.classList.add('is-cruising');\r\n  intro.hidden = false;\r\n  await openLetter({\r\n    container: intro,\r\n    pages: buildIntroPages(GAME.playerName),\r\n    skippable: true,\r\n    finalLabel: 'Respond',\r\n    onShow(index, total) {\r\n      // En el \u00FAltimo mensaje (el reto) se enciende la alerta.\r\n      if (index === total - 1 && !isAlertOn()) {\r\n        setAlert(true);\r\n        sound.alarm();\r\n      }\r\n    },\r\n  });\r\n  document.body.classList.add('is-leaving'); // fundido a negro\r\n  setTimeout(() => { window.location.href = PAGES.game; }, TIMING.fadeOutMs);\r\n}\r\n\r\nfunction start() {\r\n  if (started) return;\r\n  started = true;\r\n  sound.init();\r\n  sound.liftOff();\r\n  document.body.classList.add('is-lifting-off'); // textos fuera y la nave sube\r\n  setTimeout(showIntro, TIMING.liftOffMs);\r\n}\r\n\r\nplayButton.addEventListener('click', start);\r\ndocument.addEventListener('keydown', (event) => {\r\n  if ((event.key === 'Enter' || event.key === ' ') && !started && document.activeElement?.id !== 'sound-toggle') {\r\n    event.preventDefault();\r\n    start();\r\n  }\r\n});\r\n\r\n// Si vuelve con el bot\u00F3n \"atr\u00E1s\", dejamos la portada como nueva.\r\nwindow.addEventListener('pageshow', (event) => { if (event.persisted) window.location.reload(); });\r\n"],
